-- Review before applying: restoring original state republishes known critical defects.
-- Restores only unchanged quarantined records with this migration's exact audit entry.
DO $audit$
DECLARE r record; v_previous text; v_changed integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset($snapshot$[{"id": 2583, "tema": 18, "target": "borrador", "correcta": "b", "opciones": [{"letra": "a", "texto": "Cuando la radiación térmica total de la columna del incendio, los gases calientes y los límites calientes del compartimento generen productos inflamables por descomposición de todas las superficies combustibles expuestas."}, {"letra": "b", "texto": "Cuando la radiación térmica total de la columna del incendio, los gases calientes y los límites calientes del compartimento generen productos inflamables por pirolisis de todas las superficies combustibles expuestas."}, {"letra": "c", "texto": "Cuando la radiación térmica total de la columna del incendio, los gases calientes y los límites calientes del compartimento generen productos comburentes por pirolisis de todas las superficies combustibles expuestas."}, {"letra": "d", "texto": "Ninguna es correcta."}], "enunciado": "Condición necesaria para que se de Flas-Over..", "explicacion": "La condición necesaria para el Flash-Over es que la radiación térmica total (columna de fuego + gases calientes + límites calientes del compartimento) genere, por PIROLISIS, productos INFLAMABLES a partir de todas las superficies combustibles expuestas del recinto.", "fuente_normativa": "Manual de comportamiento del fuego en interiores (CFBT)"}, {"id": 5324, "tema": 33, "target": "borrador", "correcta": "a", "opciones": [{"letra": "a", "texto": "200 m"}, {"letra": "b", "texto": "100 m"}, {"letra": "c", "texto": "80 m"}], "enunciado": "Según el RIPCI (RD 513/2017), la distancia máxima entre dos hidrantes consecutivos situados en la vía pública (zona urbana) es de:", "explicacion": "En zona urbana, la distancia entre dos hidrantes consecutivos no debe superar los 200 m (equivalente a una distancia máxima de recorrido de 100 m desde cualquier punto protegido hasta el hidrante más cercano).", "fuente_normativa": "RD 513/2017, RIPCI (BOE-A-2017-6606)"}, {"id": 5325, "tema": 33, "target": "borrador", "correcta": "a", "opciones": [{"letra": "a", "texto": "80 m"}, {"letra": "c", "texto": "40 m"}, {"letra": "d", "texto": "100 m"}], "enunciado": "Según el RIPCI (RD 513/2017), la distancia máxima entre dos hidrantes consecutivos en zonas que no sean urbanas es de:", "explicacion": "Fuera de zona urbana, la distancia entre dos hidrantes consecutivos no debe superar los 80 m (equivalente a una distancia de recorrido de 40 m desde el punto protegido hasta el hidrante).", "fuente_normativa": "RD 513/2017, RIPCI (BOE-A-2017-6606)"}, {"id": 5507, "tema": 15, "target": "borrador", "correcta": "c", "opciones": [{"letra": "b", "texto": "Superiores a 2.000 grados C"}, {"letra": "c", "texto": "Superiores a 3.100 grados C"}, {"letra": "d", "texto": "Superiores a 5.000 grados C"}], "enunciado": "Según la NTP 495 del INSST sobre soldadura oxiacetilénica y oxicorte, la llama de un soplete de oxígeno-acetileno puede alcanzar temperaturas de:", "explicacion": "La NTP 495 del INSST indica que la llama de un soplete de acetileno-oxígeno puede superar los 3.100 grados C, lo que constituye uno de los principales riesgos de este proceso de soldadura y corte.", "fuente_normativa": "NTP 495: Soldadura oxiacetilénica y oxicorte, normas de seguridad (INSST)"}, {"id": 6556, "tema": 13, "target": "borrador", "correcta": "b", "opciones": [{"letra": "a", "texto": "Que el EPI supere los 5 kg de peso"}, {"letra": "b", "texto": "Que se presuma que el usuario no puede percibir a tiempo la inmediatez de los efectos del riesgo"}, {"letra": "d", "texto": "Que el precio del equipo supere un determinado umbral económico"}], "enunciado": "Conforme al Reglamento (UE) 2016/425, un EPI se clasifica en categoría III cuando protege frente a riesgos que pueden causar consecuencias muy graves, como la muerte o daños irreversibles para la salud, y además concurre qué circunstancia adicional?", "explicacion": "La categoría III incluye los riesgos muy graves en los que se asume que el diseñador presupone que el usuario no puede percibir a tiempo la aparición súbita de los efectos nocivos.", "fuente_normativa": "Reglamento (UE) 2016/425"}, {"id": 7843, "tema": 33, "target": "borrador", "correcta": "b", "opciones": [{"letra": "b", "texto": "200 m"}, {"letra": "c", "texto": "80 m"}, {"letra": "d", "texto": "100 m"}], "enunciado": "Según el RIPCI, la distancia máxima entre dos hidrantes consecutivos situados en la vía pública, en zona urbana, es de:", "explicacion": "En zona urbana, la distancia máxima entre hidrantes situados en la vía pública es de 200 m.", "fuente_normativa": "RD 513/2017, Anexo I"}, {"id": 7876, "tema": 33, "target": "borrador", "correcta": "b", "opciones": [{"letra": "a", "texto": "UNE 23033:2019"}, {"letra": "b", "texto": "UNE 20032:2015"}, {"letra": "c", "texto": "UNE 23035:2003"}, {"letra": "d", "texto": "UNE 23034:2023"}], "enunciado": "¿Qué norma regula los símbolos gráficos para su utilización en planos de proyecto, planes de autoprotección y planos de evacuación?", "explicacion": "La UNE 20032:2015 regula los símbolos gráficos empleados en planos de proyecto, planes de autoprotección y planos de evacuación.", "fuente_normativa": "UNE 20032:2015"}, {"id": 8653, "tema": 8, "target": "borrador", "correcta": "a", "opciones": [{"letra": "a", "texto": "Unas 260 veces mayor que la del oxígeno"}, {"letra": "b", "texto": "Unas 260 veces menor que la del oxígeno"}, {"letra": "c", "texto": "Unas 150 veces mayor que la del oxígeno"}, {"letra": "d", "texto": "Unas 200 veces mayor que la del oxígeno"}], "enunciado": "El monóxido de carbono (CO) tiene una afinidad con la hemoglobina:", "explicacion": "El CO tiene una afinidad con la hemoglobina unas 260 veces mayor que la del oxígeno, lo que explica su elevada toxicidad al desplazar al oxígeno en el transporte sanguíneo (formando carboxihemoglobina).", "fuente_normativa": "Toxicología de gases de combustión - Monóxido de carbono"}, {"id": 9313, "tema": 28, "target": "borrador", "correcta": "d", "opciones": [{"letra": "a", "texto": "Han pasado 12 meses de uso"}, {"letra": "b", "texto": "No se han verificado en los últimos 6 meses por el fabricante o laboratorio autorizado"}, {"letra": "d", "texto": "No se han verificado en un periodo de 12 meses por el fabricante o laboratorio autorizado"}], "enunciado": "Los guantes de las clases 1-2-3-4 no deberán usarse si:", "explicacion": "Los guantes de clases 1 a 4 no deben usarse si no han sido verificados en un periodo de 12 meses por el fabricante o laboratorio autorizado.", "fuente_normativa": "EPI - Guantes aislantes (IEC 60903)"}, {"id": 10098, "tema": 7, "target": "borrador", "correcta": "a", "opciones": [{"letra": "a", "texto": "Las empleadas públicas embarazadas o en periodo de lactancia"}, {"letra": "b", "texto": "Las empleadas públicas embarazadas"}, {"letra": "c", "texto": "Más de una es correcta"}, {"letra": "d", "texto": "Ninguna vale"}], "enunciado": "¿Quién tiene derecho al cambio temporal de puesto de trabajo por riesgo específico para la madre, el feto o el lactante?", "explicacion": "Tienen ese derecho las empleadas públicas embarazadas o en periodo de lactancia (art. 60).", "fuente_normativa": "Ley 8/2011, art. 60"}]$snapshot$::jsonb)
   AS x(id bigint,tema int,enunciado text,opciones jsonb,correcta text,fuente_normativa text,target text,explicacion text)
 LOOP
  PERFORM 1 FROM public.questions WHERE id=r.id FOR UPDATE;
  SELECT valor_anterior INTO v_previous FROM public.qa_changes_20260923
   WHERE question_id=r.id AND campo='estado'
    AND motivo='AUDIT-2026-10-24-30: quarantine '||r.target||'; critical content error (false, ambiguous or repealed-rule answer) found by stratified sample audit; no automatic republish'
   ORDER BY id DESC LIMIT 1;
  IF NOT FOUND THEN CONTINUE; END IF;
  UPDATE public.questions q SET estado=v_previous
   WHERE q.id=r.id AND q.estado=r.target AND q.enunciado=r.enunciado
    AND q.opciones=r.opciones AND trim(q.correcta)=r.correcta AND q.fuente_normativa=r.fuente_normativa AND q.explicacion IS NOT DISTINCT FROM r.explicacion
    AND EXISTS (SELECT 1 FROM public.topics t WHERE t.id=q.topic_id AND t.numero=r.tema AND t.convocatoria_id=1)
    AND NOT EXISTS (SELECT 1 FROM public.qa_changes_20260923 newer
      WHERE newer.question_id=r.id AND newer.campo='estado' AND newer.id>(SELECT max(id) FROM public.qa_changes_20260923
        WHERE question_id=r.id AND campo='estado' AND motivo='AUDIT-2026-10-24-30: quarantine '||r.target||'; critical content error (false, ambiguous or repealed-rule answer) found by stratified sample audit; no automatic republish'));
  GET DIAGNOSTICS v_changed = ROW_COUNT;
  IF v_changed>0 THEN
   INSERT INTO public.qa_changes_20260923(question_id,campo,valor_anterior,motivo)
    VALUES(r.id,'estado',r.target,'ROLLBACK-AUDIT-2026-10-24-30: explicit restoration of original state');
  END IF;
 END LOOP;
END $audit$;
